parameters.query:
-- Which pages to collect from. Kept in the database so adding or
-- switching off a source needs no change to this workflow.
SELECT url FROM sources WHERE active ORDER BY id;

parameters.jsCode:
// One input item per source page. Flatten them into one item per article.
// titles, urls and dates come from the same page, so their positions line up.
return $input.all().flatMap(page => {
  const titles = page.json.titles || [];
  const urls   = page.json.urls   || [];
  const dates  = page.json.dates  || [];
  return titles.map((title, i) => ({
    json: { title, url: urls[i] || '', date: dates[i] || '' }
  }));
});

// Runs once per article.
//
// $('Find articles').item is the listing row this text came from, linked by
// n8n itself. Matching by array position instead would break the moment one
// article fails to load: every later article would shift up one place and be
// saved under the wrong title, with nothing to show it had happened.
const src = $('Find articles').item.json;
const raw = $json.content || '';

// The publisher's own opening paragraph, before the line breaks are lost.
// The dashboard shows this when an item has no summary yet, and the filter
// matches keywords on it without paying for an AI call.
const text = raw.replace(/\s+/g, ' ').trim();
const looksLikeProse = s => s.length > 40 && !/^\[?https?:/.test(s);
const excerpt = (raw.split('\n').map(s => s.trim()).find(looksLikeProse) || text)
                  .slice(0, 300);

// A date we cannot read should leave the field empty, not stop the run.
let publishedAt = null;
if (src.date) {
  const d = DateTime.fromFormat(src.date.trim(), 'd.M.yyyy');
  if (d.isValid) publishedAt = d.toISO();
}

return { json: { title: src.title, url: src.url, published_at: publishedAt,
                 excerpt, text } };
